/**
 * GEMORIA — migrations.
 *
 * Version-controlled SQL, generated by Drizzle Kit from `src/db/schema`, applied
 * by the official Drizzle migrator for whichever driver is in use.
 *
 * The migrator records what it has applied in `drizzle.__drizzle_migrations`
 * inside the target database itself, so PGlite and PostgreSQL behave identically
 * and a migration is never applied twice.
 *
 * Production policy: migrations are an explicit deployment step
 * (`npm run db:migrate`) executed before the server starts. The web server does
 * not migrate itself — `DB_AUTO_MIGRATE` is refused in production by
 * `src/lib/env.ts`.
 */

import fs from 'node:fs';
import { sql } from 'drizzle-orm';
import type { DatabaseHandle } from './client';
import { migrationsFolder } from './client';

export interface MigrationStatus {
  /** Number of migrations recorded as applied in this database. */
  readonly applied: number;
  /** Wall-clock time of the most recent applied migration, ISO-8601, if any. */
  readonly lastAppliedAt: string | null;
  /** Number of migration files available on disk. */
  readonly available: number;
  readonly upToDate: boolean;
  readonly folder: string;
}

export function countMigrationFiles(folder = migrationsFolder()): number {
  if (!fs.existsSync(folder)) return 0;
  return fs
    .readdirSync(folder)
    .filter((entry) => entry.endsWith('.sql'))
    .sort()
    .length;
}

/**
 * Applies every pending migration. Idempotent: running it against an
 * up-to-date database changes nothing.
 */
export async function runMigrations(handle: DatabaseHandle): Promise<void> {
  const folder = migrationsFolder();

  if (!fs.existsSync(folder)) {
    throw new Error(
      `Migration folder not found at "${folder}". ` +
        'Run `npm run db:generate` to create migrations, or set GEMORIA_MIGRATIONS_DIR.',
    );
  }

  if (handle.driver === 'pglite') {
    const { migrate } = await import('drizzle-orm/pglite/migrator');
    await migrate(handle.db as Parameters<typeof migrate>[0], { migrationsFolder: folder });
    return;
  }

  const { migrate } = await import('drizzle-orm/node-postgres/migrator');
  await migrate(handle.db as Parameters<typeof migrate>[0], { migrationsFolder: folder });
}

/**
 * Reads the migration ledger without assuming it exists (a brand-new database
 * has not been migrated yet). Used by the health endpoint and the dashboard.
 */
export async function getMigrationStatus(
  handle: DatabaseHandle,
  folder = migrationsFolder(),
): Promise<MigrationStatus> {
  const available = countMigrationFiles(folder);

  try {
    const result = await handle.db.execute<{ applied: number; last_at: string | null }>(
      sql`select count(*)::int as applied, max(created_at) as last_at from drizzle.__drizzle_migrations`,
    );
    const row = result.rows[0];
    const applied = row?.applied ?? 0;
    const lastAt = row?.last_at ?? null;

    return {
      applied,
      lastAppliedAt: lastAt === null ? null : new Date(Number(lastAt)).toISOString(),
      available,
      upToDate: applied >= available,
      folder,
    };
  } catch {
    return { applied: 0, lastAppliedAt: null, available, upToDate: available === 0, folder };
  }
}

/** True when every table declared in the schema exists in this database. */
/**
 * Every table the migrations are expected to create.
 *
 * Named individually rather than counted: a count would pass on a database where one
 * table is missing and a stray one exists. Phase 1B has twenty; adding one means
 * adding it here, and the collection test asserts the same list.
 */
export const EXPECTED_TABLES = [
  'app_settings',
  'article_sources',
  'article_specimens',
  'article_translations',
  'articles',
  'audit_log',
  'hall_specimens',
  'hall_translations',
  'halls',
  'media_assets',
  'media_translations',
  'sessions',
  'specimen_media',
  'specimen_provenances',
  'specimen_relations',
  'specimen_translations',
  'specimens',
  'taxonomy_term_translations',
  'taxonomy_terms',
  'users',
] as const;

export async function hasSchema(handle: DatabaseHandle): Promise<boolean> {
  const result = await handle.db.execute<{ table_name: string }>(
    sql`select table_name from information_schema.tables where table_schema = 'public'`,
  );
  const present = new Set(result.rows.map((row) => row.table_name));
  return EXPECTED_TABLES.every((table) => present.has(table));
}
